<script setup lang="ts">
import { benefitText } from '@/shared/i18n'
import {computed,ref,watch} from 'vue'
import {Search,Download,ArrowUpRight} from 'lucide-vue-next'
import {data,latin,money,num,sum,months,organization,aggregateFinance,saveCSV,type FinanceRow} from './data'
import RecipientAnalysis from './RecipientAnalysis.vue'
import RegionMap from './RegionMap.vue'
const props=defineProps<{cut:string;year:number;region:string;agency:string;selectedMonths:number[]}>()
const emit=defineEmits<{region:[string];open:[FinanceRow];family:[string, string?]}>()
const query=ref(''),type=ref(''),direction=ref(''),cohort=ref(''),metric=ref('amount'),district=ref(''),sex=ref(''),age=ref(''),benefit=ref('')
const lines=computed(()=>data.finance.filter(l=>(!props.agency||l.o===props.agency)&&(!query.value||latin(l.n).toLowerCase().includes(latin(query.value).toLowerCase()))&&(!type.value||l.t===type.value)&&(!direction.value||l.d===direction.value)&&(!cohort.value||l.c===cohort.value)))
const rows=computed(()=>lines.value.map(l=>aggregateFinance(l,props.year,props.region,props.selectedMonths)).filter(r=>r.total||r.count).sort((a,b)=>metric.value==='amount'?b.total-a.total:b.count-a.count))
const regional=computed(()=>data.regions.map((name,i)=>({name,i,total:sum(lines.value.map(l=>aggregateFinance(l,props.year,String(i),props.selectedMonths).total))})))
const peopleRows=computed(()=>data.cube.filter(([d,t,s,a])=>(props.region===''||data.regionMap[data.districts[d]![0]]===+props.region)&&(district.value===''||d===+district.value)&&(benefit.value===''||t===+benefit.value)&&(sex.value===''||s===+sex.value)&&(age.value===''||a===+age.value)))
const benefitsByAmount=computed(()=>{
 const amounts=data.benefitTypes.map(()=>0)
 for(const row of peopleRows.value) amounts[row[1]]!+=sum(props.selectedMonths.map(i=>row[6][i]??0))
 return amounts.map((value,i)=>({name:data.benefitTypes[i],value,i})).filter(row=>row.value).sort((a,b)=>b.value-a.value)
})
const filteredPeople=computed(()=>data.cubePeople.filter(([d,s,a])=>(props.region===''||data.regionMap[data.districts[d]![0]]===+props.region)&&(district.value===''||d===+district.value)&&(sex.value===''||s===+sex.value)&&(age.value===''||a===+age.value)))
const peopleCount=computed(()=>{if(props.selectedMonths.length===12)return benefit.value!==''?sum(peopleRows.value.map(r=>r[4])):sum(filteredPeople.value.map(r=>r[3]));return sum(props.selectedMonths.map(i=>benefit.value!==''?sum(peopleRows.value.map(r=>r[5][i]??0)):sum(filteredPeople.value.map(r=>r[4][i]??0))))/Math.max(1,props.selectedMonths.length)})
watch(()=>props.region,()=>district.value='')
const peopleSum=computed(()=>sum(peopleRows.value.flatMap(r=>props.selectedMonths.map(i=>r[6][i]??0))))
const districts=computed(()=>data.districts.map(([r,name],i)=>({i,r,name})).filter(x=>props.region===''||data.regionMap[x.r]===+props.region))
const districtRows=computed(()=>districts.value.map(d=>({...d,amount:sum(peopleRows.value.filter(r=>r[0]===d.i).flatMap(r=>props.selectedMonths.map(i=>r[6][i]??0)))})).filter(x=>x.amount).sort((a,b)=>b.amount-a.amount))
function download(){
 if (props.cut === 'people') {
   saveCSV('Tumanlar_hisoboti.csv', [['Tuman', 'Summa, mln so‘m'], ...districtRows.value.map(row => [latin(row.name), row.amount])])
   return
 }
 if (props.cut === 'regions') {
   saveCSV('Hududlar_hisoboti.csv', [['Hudud', 'Summa, mlrd so‘m'], ...regional.value.map(row => [latin(row.name), row.total])])
   return
 }
 saveCSV('Korsatilgan_choralar.csv',[['Chora','Idora','Tanlangan summa mlrd','Oluvchilar', 'Hisob turi',...props.selectedMonths.map(i=>months[i]+' · '+(metric.value==='amount'?'mlrd so‘m':'nafar'))],...rows.value.map(r=>[latin(r.line.n),organization(r.line.o),r.total,r.line.cnt===null?'Noma’lum':r.count,r.line.k==='m'?'O‘rtacha oylik oluvchi':'Oluvchilar',...props.selectedMonths.map(i=>metric.value==='amount'?r.values[i]?.s??0:r.line.cnt===null?'—':r.values[i]?.c??0)])])}
</script>
<template><div class="np-section-stack"><Teleport defer to="#benefits-page-actions"><button class="np-button" @click="download"><Download :size="14"/>{{ benefitText("Eksport") }}</button></Teleport><template v-if="cut!=='people'"><div class="np-card"><div class="np-toolbar"><Teleport defer to="#support-filter-fields"><label class="np-search"><Search :size="15"/><input v-model="query" :placeholder="benefitText('Chora nomini qidirish')" :aria-label="benefitText('Ko‘rsatilgan chora qidiruvi')"/></label></Teleport><Teleport defer to="#support-filter-fields"><select v-model="type" :aria-label="benefitText('Ko‘mak turi')"><option value="">{{ benefitText("Barcha turlar") }}</option><option v-for="(name,key) in data.labels.types" :key="key" :value="key">{{ benefitText(name) }}</option></select></Teleport><Teleport defer to="#support-filter-fields"><select v-model="direction" :aria-label="benefitText('Ko‘mak yo‘nalishi')"><option value="">{{ benefitText("Barcha yo‘nalishlar") }}</option><option v-for="(name,key) in data.labels.directions" :key="key" :value="key">{{ benefitText(name) }}</option></select></Teleport><Teleport defer to="#support-filter-fields"><select v-model="cohort" :aria-label="benefitText('Ko‘mak toifasi')"><option value="">{{ benefitText("Barcha toifalar") }}</option><option v-for="(name,key) in data.labels.cohorts" :key="key" :value="key">{{ benefitText(name) }}</option></select></Teleport></div><div v-if="cut==='regions'" class="finance-region-grid"><RegionMap :values="regional.map(r=>r.total*1e9)" :selected="region" @select="emit('region',$event)"/><div class="region-ranking"><button v-for="r in [...regional].sort((a,b)=>b.total-a.total)" :key="r.i" :class="{selected:region===String(r.i)}" @click="emit('region',String(r.i))"><span>{{ benefitText(r.name) }}</span><b>{{ benefitText(money(r.total*1e9)) }}</b><i :style="{width:r.total/Math.max(...regional.map(x=>x.total),1)*100+'%'}"/></button></div></div><div class="np-toolbar"><p>{{ benefitText(rows.length) }}{{ benefitText(" ta chora · ") }}{{ benefitText(money(sum(rows.map(x=>x.total))*1e9)) }}{{ benefitText(" so‘m") }}</p><div class="np-segment"><button :class="{active:metric==='amount'}" @click="metric='amount'">{{ benefitText("Summa") }}</button><button :class="{active:metric==='count'}" @click="metric='count'">{{ benefitText("Oluvchilar") }}</button></div></div><div class="np-table-wrap"><table class="np-table"><thead><tr><th>{{ benefitText("Chora") }}</th><th>{{ benefitText("Idora") }}</th><th>{{ benefitText("Ko‘rsatilgan ko‘mak") }}</th><th>{{ benefitText("Oluvchilar") }}</th><th>{{ benefitText("Vedomost ijrosi") }}</th><th v-for="i in selectedMonths" :key="i">{{ benefitText(months[i]) }}<small>{{ benefitText(metric==='amount'?'mlrd so‘m':'nafar') }}</small></th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.line.id"><td><button class="text-button" @click="emit('open',row)">{{ benefitText(row.line.n) }}</button><small>{{ benefitText(data.labels.types[row.line.t]) }} · {{ benefitText(data.labels.directions[row.line.d]) }}</small></td><td>{{ benefitText(organization(row.line.o)) }}</td><td><b>{{ benefitText(money(row.total*1e9)) }}</b><small>{{ benefitText("so‘m") }}</small></td><td>{{ benefitText(row.line.cnt===null?'Ma’lumot yo‘q':num(row.count)) }}<small>{{ benefitText(row.line.k==='m'?'O‘rtacha oylik oluvchi':'Oluvchilar') }}</small></td><td><span v-if="row.plan" class="np-tag" :class="row.total/row.plan<.9?'amber':'green'">{{ num(row.total/row.plan*100,1) }}%</span><span v-else>—</span></td><td v-for="i in selectedMonths" :key="i">{{ benefitText(metric==='amount'?num(row.values[i]?.s??0,3):row.line.cnt===null?'—':num(row.values[i]?.c??0)) }}</td><td><button class="icon-button" :aria-label="benefitText(benefitText(row.line.n)+' tafsiloti')" @click="emit('open',row)"><ArrowUpRight :size="16"/></button></td></tr><tr v-if="!rows.length"><td colspan="6" class="np-empty">{{ benefitText("Tanlov bo‘yicha summa ma’lumoti yo‘q.") }}</td></tr></tbody></table></div><p class="np-note">{{ benefitText("Oluvchilar har bir chora bo‘yicha alohida sanaladi. Hududiy ma’lumotlar IHMA choralarini qamraydi.") }}</p></div></template><template v-else><div class="np-notice blue">{{ benefitText("Nafaqa bazasi · 2025-yil") }}</div><section class="np-card"><div class="np-toolbar"><Teleport defer to="#support-filter-fields"><select v-model="district" :aria-label="benefitText('Fuqaro tumani')"><option value="">{{ benefitText("Barcha tumanlar") }}</option><option v-for="d in districts" :key="d.i" :value="String(d.i)">{{ benefitText(d.name) }}</option></select></Teleport><Teleport defer to="#support-filter-fields"><select v-model="benefit" :aria-label="benefitText('Nafaqa turi')"><option value="">{{ benefitText("Barcha nafaqa turlari") }}</option><option v-for="(name,i) in data.benefitTypes" :key="i" :value="String(i)">{{ benefitText(name) }}</option></select></Teleport><Teleport defer to="#support-filter-fields"><select v-model="sex" :aria-label="benefitText('Jins')"><option value="">{{ benefitText("Barcha jinslar") }}</option><option value="0">{{ benefitText("Erkak") }}</option><option value="1">{{ benefitText("Ayol") }}</option></select></Teleport><Teleport defer to="#support-filter-fields"><select v-model="age" :aria-label="benefitText('Yosh guruhi')"><option value="">{{ benefitText("Barcha yoshlar") }}</option><option v-for="(name,i) in ['18 yoshgacha','18–29 yosh','30–59 yosh','60 va undan katta']" :key="i" :value="String(i)">{{ benefitText(name) }}</option></select></Teleport></div><div class="people-metrics"><div><span>{{ benefitText(selectedMonths.length===12?'Kesimdagi yillik hisoblar':'O‘rtacha oylik oluvchilar') }}</span><strong>{{ num(peopleCount) }}</strong><small>{{ benefitText("Hududlararo takrorlar bo‘lishi mumkin") }}</small></div><div><span>{{ benefitText("Tanlangan oylarda to‘lov") }}</span><strong>{{ benefitText(money(peopleSum*1e6)) }}</strong><small>{{ benefitText("so‘m") }}</small></div><div><span>{{ benefitText("Tumanlar") }}</span><strong>{{ benefitText(districtRows.length) }}</strong><small>{{ benefitText("To‘lov ma’lumoti mavjud") }}</small></div></div><div class="finance-region-grid"><div><h3>{{ benefitText("Tumanlar bo‘yicha to‘lov") }}</h3><div class="district-scroll"><button v-for="d in districtRows" :key="d.i" class="district-row" @click="district=district===String(d.i)?'':String(d.i)"><span>{{ benefitText(d.name) }}</span><b>{{ benefitText(money(d.amount*1e6)) }}</b></button></div></div><div><h3>{{ benefitText("Nafaqa turlari bo‘yicha to‘lov") }}</h3><div class="district-scroll"><button v-for="row in benefitsByAmount" :key="row.i" class="district-row" @click="benefit=benefit===String(row.i)?'':String(row.i)"><span>{{ benefitText(row.name) }}</span><b>{{ benefitText(money(row.value*1e6)) }}</b></button></div></div></div></section><RecipientAnalysis :region="region" :district="district" :benefit="benefit" :sex="sex" :age="age" :selected-months="selectedMonths" @family="(family,member)=>emit('family',family,member)"/></template></div></template>
<style scoped>.finance-region-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:20px 0}.region-ranking{display:grid;gap:5px}.region-ranking button{display:flex;justify-content:space-between;position:relative;gap:15px;font-size:11px;text-align:left;padding:8px 0;color:var(--muted-foreground)}.region-ranking button b{color:#496d9e;white-space:nowrap}.region-ranking button i{position:absolute;bottom:0;left:0;height:2px;background:#abc0f0;transition:width .5s}.region-ranking button.selected{background:#edf3ff}.np-table td:first-child{min-width:270px}.people-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:22px 0}.people-metrics>div{display:grid;gap:8px;background:var(--muted);padding:22px;border-radius:10px}.people-metrics span{font-size:11px;color:var(--muted-foreground)}.people-metrics strong{font-size:28px;color:#4069ad}.people-metrics small{font-size:11px;color:var(--muted-foreground)}.district-scroll{max-height:460px;overflow:auto;margin-top:15px}.district-row{display:flex;justify-content:space-between;align-items:center;gap:15px;text-align:left;width:100%;font-size:11px;padding:12px 4px;border-bottom:1px solid var(--border);color:var(--muted-foreground)}.district-row small{display:block;font-size:11px;color:var(--muted-foreground)}.district-row b{color:#466c9e}.np-notice+.np-card{margin-top:20px}@media(max-width:850px){.finance-region-grid{grid-template-columns:1fr}.people-metrics{grid-template-columns:1fr}}</style>
